compile.workshop:
variables {
    global:
        0: g
}

rule ("context player components") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Global Variable(g, X Component Of(Event Player));
        Set Global Variable(g, Y Component Of(Event Player));
        Set Global Variable(g, Z Component Of(Event Player));
    }
}

